  lifeEvents: LifeEvent[],
  outputLanguage: string,
  exSpouseDetails?: SpouseDetails,
  visuals?: Visuals,
  isChatContext: boolean = false
): string {
  const today = new Date();
  const dateString = today.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

  let prompt = isChatContext 
    ? `You are the "Universal Siddhanta Oracle", a master of synthesizing Western Astrology, Vedic Jyotish (Navagraha), Chaldean Numerology (9-5-1 System), and daily Rashifal. You analyze the 9 Planets and the Willpower Line specifically. Respond with deep spiritual resonance.`
    : `Generate a Comprehensive Cosmic Synthesis Report. Current Date: ${dateString}. Focus on Navagraha and the 9-5-1 Willpower Axis.`;

  if (outputLanguage === 'Gujarati') {
    prompt += ` Respond ONLY in Gujarati. Use sophisticated terminology from the Vedas and Puranas.`;
