      birthDetails: { name: 'Harshkumar Patel', dob: '1995-01-17', tob: '15:58', pob: 'Vadodara, Gujarat' },
      lifeEvents: [{ planet: 'Sun', date: '1995-01-17', description: 'Birth Alignment' }],
      readingHistory: [],
      chatHistory: [],
      outputLanguage: 'English'
    };
  });

  const chatEndRef = useRef<HTMLDivElement>(null);

  // Sync to Cloud
  const sync = useCallback(async (newState: AppState) => {
    try {
      const userRef = ref(db, `users/${userId}`);
      await set(userRef, { ...newState, lastUpdated: new Date().toISOString() });
      localStorage.setItem(STORAGE_KEY, JSON.stringify(newState));
      setIsSynced(true);
    } catch (e) {
      console.error("Sync error:", e);
    }
  }, [userId, db]);

  // Load from Cloud
  useEffect(() => {
    const userRef = ref(db, `users/${userId}`);
    get(userRef).then(snap => {
      if (snap.exists()) {
        const data = snap.val();
        setState(prev => ({ ...prev, ...data }));
        setIsSynced(true);
      }
    });
  }, [userId, db]);

  const handleUpdateDetails = (updates: Partial<BirthDetails>) => {
    const next = { ...state, birthDetails: { ...state.birthDetails, ...updates } };
    setState(next);
    sync(next);
  };

  const handleAddEvent = () => {
    const next = { ...state, lifeEvents: [...state.lifeEvents, { planet: 'Mars', date: '', description: '' }] };
    setState(next);
    sync(next);
  };

  const handleUpdateEvent = (index: number, updates: Partial<LifeEvent>) => {
    const nextEvents = [...state.lifeEvents];
    nextEvents[index] = { ...nextEvents[index], ...updates };
    const next = { ...state, lifeEvents: nextEvents };
    setState(next);
    sync(next);
  };

  const generateReading = async () => {
    setLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Perform a Navagraha synthesis for ${state.birthDetails.name}, born ${state.birthDetails.dob} at ${state.birthDetails.tob}. Language: ${state.outputLanguage}. Include projections for 2030 and 2050. Focus on the 9-5-1 willpower axis. Format in detailed Markdown.`;

      const response = await ai.models.generateContent({
        model: GEMINI_MODEL,
        contents: prompt,
        config: { tools: [{ googleSearch: {} }] }
      });

      const resultText = response.text || "The Oracle is silent.";
      setReading(resultText);

      // Archive the reading
      const newArchive: ReadingArchive = {
        id: Math.random().toString(36).substring(2, 9),
        date: new Date().toISOString().split('T')[0],
        text: resultText,
        title: `Celestial Synthesis: ${new Date().toLocaleDateString()}`
      };

      const next = { ...state, readingHistory: [newArchive, ...state.readingHistory] };
      setState(next);
      sync(next);
    } catch (e: any) {
      setReading("Error: " + e.message);
    } finally {
      setLoading(false);
    }
  };

  const sortedTimeline = useMemo(() => {
    const events = state.lifeEvents.map(e => ({ ...e, type: 'event' }));
    const readings = state.readingHistory.map(r => ({ date: r.date, description: r.title, planet: 'Jupiter', type: 'reading', text: r.text }));
    return [...events, ...readings].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [state.lifeEvents, state.readingHistory]);

  return (
    <div className="max-w-6xl mx-auto p-6 md:p-12 min-h-screen">
      <header className="text-center mb-12">
        <h1 className="font-serif text-5xl md:text-6xl text-white font-bold bg-clip-text text-transparent bg-gradient-to-b from-white to-indigo-500 mb-2 tracking-tighter">Cosmic Compass</h1>
        <p className="text-indigo-300/60 text-xs font-bold uppercase tracking-widest mb-6">Navagraha & Willpower Synthesis</p>
        <div className="flex justify-center space-x-3">
          <span className={`text-[10px] uppercase font-black px-3 py-1 rounded-full border ${isSynced ? 'border-indigo-500/30 text-indigo-400 bg-indigo-500/10' : 'border-amber-500/30 text-amber-400 bg-amber-500/10 animate-pulse'}`}>
            {isSynced ? 'Akashic Sync Active' : 'Connecting...'}
          </span>
        </div>
      </header>

      <div className="flex justify-center mb-10">
        <div className="glass p-1 rounded-2xl flex space-x-1 shadow-2xl border border-white/10">
          <button onClick={() => setActiveTab('profile')} className={`px-6 md:px-10 py-3 rounded-xl text-xs font-bold transition-all ${activeTab === 'profile' ? 'bg-indigo-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}>Profile</button>
          <button onClick={() => setActiveTab('chronicle')} className={`px-6 md:px-10 py-3 rounded-xl text-xs font-bold transition-all ${activeTab === 'chronicle' ? 'bg-indigo-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}>Timeline</button>
          <button onClick={() => setActiveTab('oracle')} className={`px-6 md:px-10 py-3 rounded-xl text-xs font-bold transition-all ${activeTab === 'oracle' ? 'bg-indigo-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}>Oracle</button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        {activeTab === 'profile' && (
          <>
            <div className="lg:col-span-5 space-y-6">
              <section className="glass p-8 rounded-[2rem] glow-border">
                <h2 className="font-serif text-2xl mb-6 text-white flex items-center">
                  <span className="text-indigo-500 mr-3">✧</span> Birth Profile
                </h2>
                <InputField label="Full Name" type="text" value={state.birthDetails.name} onChange={(e: any) => handleUpdateDetails({ name: e.target.value })} />
                <div className="grid grid-cols-2 gap-4">
                  <InputField label="Date" type="date" value={state.birthDetails.dob} onChange={(e: any) => handleUpdateDetails({ dob: e.target.value })} />
                  <InputField label="Time" type="time" value={state.birthDetails.tob} onChange={(e: any) => handleUpdateDetails({ tob: e.target.value })} />
                </div>
                <InputField label="Place" type="text" value={state.birthDetails.pob} onChange={(e: any) => handleUpdateDetails({ pob: e.target.value })} />
              </section>

              <section className="glass p-8 rounded-[2rem] glow-border">
                <h2 className="font-serif text-2xl mb-6 text-white flex items-center">
                  <span className="text-amber-500 mr-3">⧉</span> 9-5-1 Axis
                </h2>
                <div className="grid grid-cols-3 gap-2 max-w-[150px] mx-auto mb-4">
                  {[4, 9, 2, 3, 5, 7, 8, 1, 6].map(n => (
                    <div key={n} className={`aspect-square flex items-center justify-center rounded-lg text-xs font-bold border transition-all ${[9, 5, 1].includes(n) ? 'bg-indigo-600 text-white border-indigo-400 shadow-[0_0_15px_rgba(79,70,229,0.5)]' : 'bg-white/5 text-gray-700 border-transparent'}`}>{n}</div>
                  ))}
                </div>
                <p className="text-[10px] text-gray-500 text-center uppercase tracking-widest font-bold">Resilience & Manifestation Path</p>
              </section>
            </div>

            <div className="lg:col-span-7 space-y-6">
              <button 
                onClick={generateReading} 
                disabled={loading}
                className="w-full py-10 bg-indigo-600 hover:bg-indigo-500 text-white font-bold text-xl rounded-[2.5rem] shadow-2xl transition-all disabled:opacity-50 relative overflow-hidden group"
              >
                <span className="relative z-10">{loading ? 'Interrogating the Stars...' : 'Generate New Synthesis'}</span>
              </button>

              {reading && (
                <div className="glass p-10 rounded-[2.5rem] border border-white/10 animate-in fade-in slide-in-from-bottom-4">
                  <div className="prose prose-invert max-w-none text-gray-200 text-sm leading-relaxed whitespace-pre-wrap">{reading}</div>
                </div>
              )}
            </div>
          </>
        )}

        {activeTab === 'chronicle' && (
          <div className="lg:col-span-12 space-y-8 animate-in fade-in duration-500">
            <div className="flex justify-between items-center mb-4">
              <h2 className="font-serif text-3xl text-white">The Karmic Chronicle</h2>
              <button onClick={handleAddEvent} className="bg-indigo-600/20 hover:bg-indigo-600/40 text-indigo-300 text-[10px] font-black uppercase px-4 py-2 rounded-full border border-indigo-500/20 transition-all">+ Add Milestone</button>
            </div>

            <div className="relative pl-10 md:pl-20 py-10">
              <div className="absolute left-10 md:left-20 top-0 bottom-0 w-0.5 bg-gradient-to-b from-indigo-500/0 via-indigo-500/30 to-indigo-500/0"></div>

              {sortedTimeline.length === 0 ? (
                <div className="text-center py-20 opacity-30 italic text-sm">No milestones found in your Sutra.</div>
              ) : (
                sortedTimeline.map((item, i) => (
                  <div key={i} className="mb-12 relative">
                    {/* Timeline Node */}
                    <div className={`absolute -left-[5px] top-1 w-2.5 h-2.5 rounded-full z-10 shadow-[0_0_10px_rgba(79,70,229,0.5)] ${item.type === 'reading' ? 'bg-amber-400' : 'bg-indigo-500'}`}></div>

                    <div className="flex flex-col md:flex-row md:items-start space-y-4 md:space-y-0 md:space-x-8">
                      <div className="md:w-32 flex-shrink-0 pt-1">
                        <span className="text-[10px] font-black uppercase tracking-widest text-indigo-400/60">{item.date || 'Undated'}</span>
                      </div>

                      <div className={`flex-1 glass p-6 rounded-3xl border border-white/5 shadow-xl transition-all hover:border-white/20 ${item.type === 'reading' ? 'border-amber-500/20 bg-amber-500/5' : ''}`}>
                        <div className="flex justify-between items-start mb-2">
                          <span className="text-[10px] font-black uppercase tracking-widest text-indigo-300">{item.planet || 'Neutral'} Node</span>
                          {item.type === 'reading' && <span className="text-[9px] bg-amber-500/20 text-amber-400 px-2 py-0.5 rounded-full font-bold uppercase">Oracle Record</span>}
                        </div>

                        {item.type === 'event' ? (
                          <div className="space-y-3">
                            <input 
                              type="date" 
                              value={item.date} 
                              onChange={(e) => handleUpdateEvent(i, { date: e.target.value })}
                              className="bg-transparent text-[10px] text-gray-500 outline-none block"
                            />
                            <textarea 
                              value={item.description} 
                              onChange={(e) => handleUpdateEvent(i, { description: e.target.value })}
                              placeholder="Describe this karmic milestone..."
                              className="w-full bg-transparent text-sm text-gray-200 outline-none resize-none"
                              rows={2}
                            />
                          </div>
                        ) : (
                          <div className="space-y-3">
                            <h3 className="text-white font-bold text-sm">{item.description}</h3>
                            <p className="text-gray-400 text-xs line-clamp-3 italic">"{item.text?.substring(0, 150)}..."</p>
                            <button 
                              onClick={() => { setReading(item.text || ''); setActiveTab('profile'); }}
                              className="text-[10px] text-amber-400 font-bold hover:underline"
                            >
                              Read Full Scroll →
                            </button>
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        )}

        {activeTab === 'oracle' && (
          <div className="lg:col-span-12 glass h-[70vh] rounded-[3rem] flex flex-col overflow-hidden shadow-2xl animate-in zoom-in-95">
             <div className="p-6 bg-white/5 border-b border-white/10 flex justify-between items-center">
                <h2 className="text-xl font-bold text-white flex items-center"><span className="mr-3">🔮</span> Oracle Chat</h2>
                <span className="text-[9px] text-indigo-400 uppercase font-bold tracking-widest">Akashic Link Active</span>
             </div>
             <div className="flex-1 p-8 overflow-y-auto space-y-6">
                <div className="flex justify-start">
                   <div className="bg-white/5 border border-white/10 px-5 py-3 rounded-2xl max-w-[80%]">
                      <p className="text-sm text-gray-300">I am the Siddhanta Oracle. How can I guide your 9-5-1 axis today?</p>
                   </div>
                </div>
                {state.chatHistory.map((msg, i) => (
                  <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                    <div className={`px-5 py-3 rounded-2xl max-w-[80%] border ${msg.role === 'user' ? 'bg-indigo-600/30 border-indigo-500/40 text-white' : 'bg-white/5 border-white/10 text-gray-300'}`}>
                      <p className="text-sm whitespace-pre-wrap">{msg.text}</p>
                    </div>
                  </div>
                ))}
                <div ref={chatEndRef} />
             </div>
             <div className="p-6 bg-white/5 border-t border-white/10">
                <p className="text-center text-[9px] text-gray-600 uppercase font-black mb-3">Live Session Recording Enabled</p>
                <div className="flex space-x-4">
                   <input className="flex-1 bg-black/40 border border-white/10 rounded-2xl px-6 py-4 text-sm text-white focus:outline-none focus:ring-2 focus:ring-indigo-500/40" placeholder="Query the stars..." />
                   <button className="bg-indigo-600 px-8 rounded-2xl font-bold text-white hover:bg-indigo-500 transition-all">Ask</button>
                </div>
             </div>
          </div>
        )}
      </div>
    </div>
  );
};

// --- Mount ---
const root = ReactDOM.createRoot(document.getElementById('root')!);
root.render(<App />);

// services/firebaseService.ts
// Standard modular imports for Firebase v9+ to ensure compatibility and correct symbol resolution
import { initializeApp, getApps, getApp } from 'firebase/app';
import { getDatabase, ref, set, get } from 'firebase/database';

const firebaseConfig = {
  apiKey: "AIzaSyDrFjYv2c322zzCMsgpVttjUz9lWDrBoUg",
  authDomain: "cosmic-compass-5fd5e.firebaseapp.com",
  databaseURL: "https://cosmic-compass-5fd5e-default-rtdb.europe-west1.firebasedatabase.app",
  projectId: "cosmic-compass-5fd5e",
  storageBucket: "cosmic-compass-5fd5e.firebasestorage.app",
  messagingSenderId: "160679439170",
  appId: "1:160679439170:web:bafbb80eb30f64ee9476db"
};

/**
 * Robust singleton initialization for Firebase.
 * Using getApps() to check for existing instances prevents "Firebase: App named '[DEFAULT]' already exists" errors.
 */
const app = getApps().length === 0 ? initializeApp(firebaseConfig) : getApp();

/**
 * Initialize Database
 */
export const db = getDatabase(app);

/**
 * Gets or creates a persistent unique ID for this device/browser.
 */
export const getOrGenerateUserId = (): string => {
  let userId = localStorage.getItem('cosmic_user_id');
  if (!userId) {
    userId = 'user_' + Math.random().toString(36).substring(2, 11) + Date.now().toString(36);
    localStorage.setItem('cosmic_user_id', userId);
  }
  return userId;
};

/**
 * Saves the entire app state to Firebase Realtime Database.
 */
export const syncToFirebase = async (userId: string, data: any) => {
  try {
    const userRef = ref(db, `users/${userId}`);
    await set(userRef, {
      ...data,
      lastUpdated: new Date().toISOString()
    });
    return true;
  } catch (error) {
    console.error("Firebase Sync Error:", error);
    return false;
  }
};

/**
 * Fetches the app state from Firebase Realtime Database.
 */
export const loadFromFirebase = async (userId: string): Promise<any | null> => {
  try {
    const userRef = ref(db, `users/${userId}`);
    const snapshot = await get(userRef);
    if (snapshot.exists()) {
      return snapshot.val();
    }
    return null;
  } catch (error) {
    console.error("Firebase Load Error:", error);
    return null;
  }
};
